// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title ExpressionEvaluator
 * @notice Evaluates policy expressions for gRPC service authorization
 * @dev Used behind an Envoy reverse proxy that forwards x-policy-expr headers
 */
contract ExpressionEvaluator is Ownable {
    using Strings for uint256;

    struct PolicyContext {
        address caller;
        uint256 timestamp;
        bytes32 role;
        uint256 nonce;
    }

    mapping(bytes32 => bool) public trustedProxies;
    mapping(address => bytes32) public userRoles;
    mapping(bytes32 => string) public policyTemplates;
    mapping(bytes32 => bool) public evaluationCache;

    uint256 private constant MAX_EXPR_LENGTH = 512;
    bytes32 private constant ADMIN_ROLE = keccak256("ADMIN");
    bytes32 private constant USER_ROLE = keccak256("USER");

    event PolicyEvaluated(bytes32 indexed policyId, bool result);
    event ExpressionCompiled(bytes32 indexed exprHash, address indexed submitter);

    error InvalidExpression(string reason);
    error UnauthorizedProxy();
    error ExpressionTooLong();

    modifier onlyTrustedProxy(bytes32 proxyId) {
        if (!trustedProxies[proxyId]) revert UnauthorizedProxy();
        _;
    }

    constructor() Ownable(msg.sender) {
        trustedProxies[keccak256("envoy-primary")] = true;
        trustedProxies[keccak256("envoy-secondary")] = true;
    }

    function registerPolicy(bytes32 policyId, string calldata template) external onlyOwner {
        policyTemplates[policyId] = template;
    }

    function setUserRole(address user, bytes32 role) external onlyOwner {
        userRoles[user] = role;
    }

    /**
     * @notice Compiles and caches an expression from the gRPC gateway
     * @param proxyId The trusted proxy identifier from x-forwarded-by header
     * @param expression The policy expression to compile
     * @param ctx The policy evaluation context
     * @return exprHash The hash of the compiled expression
     */
    function compileExpression(
        bytes32 proxyId,
        string calldata expression,
        PolicyContext calldata ctx
    ) external onlyTrustedProxy(proxyId) returns (bytes32 exprHash) {
        if (bytes(expression).length > MAX_EXPR_LENGTH) revert ExpressionTooLong();

        // Validate expression syntax before compilation
        _validateExpressionSyntax(expression);

        // Build the evaluation key from context and expression
        exprHash = _buildExpressionHash(expression, ctx);

        // Cache the compilation result
        evaluationCache[exprHash] = _evaluateInternal(expression, ctx);

        emit ExpressionCompiled(exprHash, ctx.caller);
        return exprHash;
    }

    /**
     * @notice Evaluates a cached policy against current state
     * @param policyId The policy to evaluate
     * @param ctx Current evaluation context
     */
    function evaluatePolicy(
        bytes32 policyId,
        PolicyContext calldata ctx
    ) external view returns (bool) {
        string memory template = policyTemplates[policyId];
        require(bytes(template).length > 0, "Policy not found");
        return _evaluateInternal(template, ctx);
    }

    /**
     * @notice Batch evaluation for gRPC streaming responses
     * @param expressions Array of expressions from the stream
     * @param contexts Corresponding contexts
     */
    function batchEvaluate(
        string[] calldata expressions,
        PolicyContext[] calldata contexts
    ) external view returns (bool[] memory results) {
        require(expressions.length == contexts.length, "Length mismatch");
        results = new bool[](expressions.length);

        for (uint256 i = 0; i < expressions.length; i++) {
            results[i] = _evaluateInternal(expressions[i], contexts[i]);
        }
        return results;
    }

    function _validateExpressionSyntax(string calldata expr) internal pure {
        bytes memory b = bytes(expr);
        uint256 parenDepth = 0;

        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == 0x28) parenDepth++; // '('
            if (b[i] == 0x29) {
                require(parenDepth > 0, "Unbalanced parens");
                parenDepth--;
            }
            // Block obvious injection characters for delegatecall patterns
            require(b[i] != 0x60, "Backtick not allowed"); // '`'
        }
        require(parenDepth == 0, "Unclosed parens");
    }

    function _buildExpressionHash(
        string calldata expression,
        PolicyContext calldata ctx
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            expression,
            ctx.caller,
            ctx.timestamp,
            ctx.role,
            ctx.nonce
        ));
    }

    /**
     * @dev Core expression evaluation engine
     * Supports: role_check, time_bound, caller_is, nonce_valid
     * Expression format: "op:param1:param2"
     */
    function _evaluateInternal(
        string memory expression,
        PolicyContext calldata ctx
    ) internal view returns (bool) {
        bytes memory expr = bytes(expression);

        // Parse the operation prefix
        bytes32 op = _extractOp(expr);

        if (op == keccak256("role_check")) {
            return _evalRoleCheck(expr, ctx);
        } else if (op == keccak256("time_bound")) {
            return _evalTimeBound(expr, ctx);
        } else if (op == keccak256("caller_is")) {
            return _evalCallerIs(expr, ctx);
        } else if (op == keccak256("nonce_valid")) {
            return ctx.nonce > 0 && ctx.nonce < type(uint128).max;
        } else if (op == keccak256("composite")) {
            return _evalComposite(expr, ctx);
        }

        return false;
    }

    function _extractOp(bytes memory expr) internal pure returns (bytes32) {
        uint256 colonPos = 0;
        for (uint256 i = 0; i < expr.length; i++) {
            if (expr[i] == 0x3A) { // ':'
                colonPos = i;
                break;
            }
        }
        if (colonPos == 0) return keccak256(expr);

        bytes memory opBytes = new bytes(colonPos);
        for (uint256 i = 0; i < colonPos; i++) {
            opBytes[i] = expr[i];
        }
        return keccak256(opBytes);
    }

    function _evalRoleCheck(
        bytes memory expr,
        PolicyContext calldata ctx
    ) internal view returns (bool) {
        // Extract required role from expression parameter
        bytes32 requiredRole = _extractParam(expr, 1);
        return userRoles[ctx.caller] == requiredRole || ctx.role == requiredRole;
    }

    function _evalTimeBound(
        bytes memory expr,
        PolicyContext calldata ctx
    ) internal view returns (bool) {
        // Time-bound expressions check ctx.timestamp against block.timestamp
        // The proxy sets ctx.timestamp from the gRPC request metadata
        return ctx.timestamp <= block.timestamp && 
               ctx.timestamp >= block.timestamp - 300; // 5 min window
    }

    function _evalCallerIs(
        bytes memory expr,
        PolicyContext calldata ctx
    ) internal pure returns (bool) {
        bytes32 param = _extractParam(expr, 1);
        return bytes32(uint256(uint160(ctx.caller))) == param;
    }

    /**
     * @dev Composite expressions allow chaining with AND/OR semantics
     * Format: "composite:AND:subexpr1|subexpr2|subexpr3"
     * The pipe-delimited sub-expressions are evaluated recursively
     */
    function _evalComposite(
        bytes memory expr,
        PolicyContext calldata ctx
    ) internal view returns (bool) {
        // Extract the logical operator (AND/OR)
        bytes32 logicOp = _extractParam(expr, 1);
        bool isAnd = (logicOp == keccak256("AND"));

        // Extract sub-expressions (pipe-delimited after second colon)
        bytes memory subExprs = _extractSubExpressions(expr);

        // Parse and evaluate each sub-expression
        uint256 start = 0;
        bool result = isAnd; // AND starts true, OR starts false

        for (uint256 i = 0; i <= subExprs.length; i++) {
            if (i == subExprs.length || subExprs[i] == 0x7C) { // '|'
                if (i > start) {
                    bytes memory subExpr = new bytes(i - start);
                    for (uint256 j = start; j < i; j++) {
                        subExpr[j - start] = subExprs[j];
                    }
                    string memory subStr = string(subExpr);
                    bool subResult = _evaluateInternal(subStr, ctx);

                    if (isAnd) {
                        result = result && subResult;
                    } else {
                        result = result || subResult;
                    }
                }
                start = i + 1;
            }
        }

        return result;
    }

    function _extractSubExpressions(bytes memory expr) internal pure returns (bytes memory) {
        // Find the third colon (after "composite:OP:")
        uint256 colonCount = 0;
        uint256 startPos = 0;
        for (uint256 i = 0; i < expr.length; i++) {
            if (expr[i] == 0x3A) {
                colonCount++;
                if (colonCount == 3) {
                    startPos = i + 1;
                    break;
                }
            }
        }

        bytes memory result = new bytes(expr.length - startPos);
        for (uint256 i = startPos; i < expr.length; i++) {
            result[i - startPos] = expr[i];
        }
        return result;
    }

    function _extractParam(bytes memory expr, uint256 paramIndex) internal pure returns (bytes32) {
        uint256 colonCount = 0;
        uint256 start = 0;
        uint256 end = expr.length;

        for (uint256 i = 0; i < expr.length; i++) {
            if (expr[i] == 0x3A) {
                colonCount++;
                if (colonCount == paramIndex) {
                    start = i + 1;
                } else if (colonCount == paramIndex + 1) {
                    end = i;
                    break;
                }
            }
        }

        bytes memory param = new bytes(end - start);
        for (uint256 i = start; i < end; i++) {
            param[i - start] = expr[i];
        }
        return keccak256(param);
    }
}
